using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Globalization;using System.Reflection;using UnityEngine;using Unity.Profiling;using LighFight.Runtime;using LighFight.Core;
public sealed class NativeSupportMainProbe:MonoBehaviour {
 [Serializable]public class FootSet{public string prefabName;public int vertexCount;public int[] indices;}
 public GameObject[] prefabs;public FootSet[] footSets;public Camera captureCamera;public bool quitWhenComplete=true;
 [Serializable]class Summary{public string output,unityVersion,error;public bool completed;public bool failed;public int samples,vertices;public float worstFloor,maxSurfaceError,maxRootXZ;public string profiling="Main/Render Thread recorder nanoseconds converted to ms;0 means unavailable. Benchmark rows exclude diagnostic BakeMesh/Camera.Render.";}
 Summary summary=new Summary();List<string> rows=new List<string>{"character,state,segment,frame,phase,blend,bodyMode,fullFloor,fullBody,proxyMiss,surfaceError,rootXZ,bakeMs,renderMs,mainThreadMs,renderThreadMs,frameMs"};string output;ProfilerRecorder main,render;static string F(double x)=>x.ToString("R",CultureInfo.InvariantCulture);
 IEnumerator Start(){var run=Run();float deadline=Time.realtimeSinceStartup+600;while(true){bool more=false;object yielded=null;Exception failure=null;try{if(Time.realtimeSinceStartup>deadline)throw new TimeoutException("Main native probe exceeded600seconds");more=run.MoveNext();if(more)yielded=run.Current;}catch(Exception ex){failure=ex;}if(failure!=null){summary.failed=true;summary.error=failure.ToString();if(output==null){output=Path.GetFullPath(Environment.GetEnvironmentVariable("LIGHTFIGHT_NATIVE_PROBE_OUTPUT")??Path.Combine(Application.persistentDataPath,"NativeSupportMainProbe-failed"));Directory.CreateDirectory(output);summary.output=output;}File.WriteAllLines(Path.Combine(output,"frames.csv"),rows);File.WriteAllText(Path.Combine(output,"summary.json"),JsonUtility.ToJson(summary,true));Debug.LogError("NATIVE_MAIN_PROBE_FAILED "+summary.error);if(quitWhenComplete)Application.Quit(1);yield break;}if(!more)yield break;yield return yielded;}}
 IEnumerator Run(){output=Path.GetFullPath(Environment.GetEnvironmentVariable("LIGHTFIGHT_NATIVE_PROBE_OUTPUT")??Path.Combine(Application.persistentDataPath,"NativeSupportMainProbe",DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")));Directory.CreateDirectory(output);summary.output=output;summary.unityVersion=Application.unityVersion;main=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread",128);render=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Render Thread",128);
 foreach(var prefab in prefabs){var actor=Instantiate(prefab);var o=actor.GetComponent<NativeSupportOverlay>();var g=actor.GetComponent<CandidateFootGrounding>();var v=actor.GetComponent<FighterView>();var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();if(!o||!o.enabled||!g.enabled)throw new Exception("Integrated native overlay/grounding missing "+prefab.name);skin.updateWhenOffscreen=true;skin.forceMatrixRecalculationPerRender=true;v.PoseTowards(new Fighter{Guard=true},new Fighter{X=1,Guard=true},0);o.animator.speed=1;if(!o.animator.HasState(0,Animator.StringToHash("Base Layer.jab")))throw new Exception("Main lowercase jab state missing "+prefab.name);
 var refActor=Instantiate(prefab);foreach(var b in refActor.GetComponentsInChildren<MonoBehaviour>())b.enabled=false;foreach(var a in refActor.GetComponentsInChildren<Animator>())a.enabled=false;foreach(var r in refActor.GetComponentsInChildren<Renderer>())r.enabled=false;var rs=refActor.GetComponentInChildren<SkinnedMeshRenderer>();var ro=refActor.GetComponent<NativeSupportOverlay>();var refHip=rs.bones.Single(t=>t.name.Substring(t.name.LastIndexOf(':')+1)=="Hips");var footSet=footSets.Single(f=>f.prefabName==prefab.name);var feet=footSet.indices;if(feet==null||feet.Length==0||footSet.vertexCount<=0||feet.Any(i=>i<0||i>=footSet.vertexCount))throw new Exception("Invalid serialized original foot set "+prefab.name);if(skin.sharedMesh.vertexCount!=footSet.vertexCount)throw new Exception("Original imported vertex count changed "+prefab.name);

 foreach(var e in o.entries.Where(e=>new[]{"Greeting","Dance","Walk","Defeat","Victory"}.Contains(e.state))){o.animator.Play("Base Layer.jab",0,.30f);o.animator.speed=1;yield return new WaitForSeconds(.18f);
 // Exercise the integrated FighterView preview API once, then let ordinary Animator evaluation advance.
 var preview=typeof(FighterView).GetMethod("PreviewNativeMotion",BindingFlags.Public|BindingFlags.Instance);if(preview==null||!(bool)preview.Invoke(v,new object[]{e.state,.825f*e.pose.duration}))throw new Exception("FighterView native dispatch failed "+e.state);o.animator.speed=1;
 foreach(string segment in new[]{"entry","settled","return","benchmark"}){if(segment=="settled"){float until=Time.realtimeSinceStartup+2;while(o.LastBlendWeight<1&&Time.realtimeSinceStartup<until)yield return null;}if(segment=="return"){o.animator.Play("Base Layer.jab",0,.30f);o.animator.speed=1;}if(segment=="benchmark"){o.animator.Play(e.state,0,.25f);o.animator.speed=1;yield return new WaitForSeconds(.4f);}int count=segment=="benchmark"?120:segment=="settled"?1:24;
 for(int frame=0;frame<count;frame++){yield return new WaitForSeconds(1f/60);yield return new WaitForEndOfFrame();if(segment=="benchmark"){rows.Add(string.Join(",",prefab.name,e.state,segment,frame,F(o.LastSamplePhase),F(o.LastBlendWeight),"", "","","","","","","",F(main.LastValue/1e6),F(render.LastValue/1e6),F(Time.unscaledDeltaTime*1000)));continue;}
 var clock=System.Diagnostics.Stopwatch.StartNew();captureCamera.Render();double renderMs=clock.Elapsed.TotalMilliseconds;clock.Restart();var mesh=new Mesh();skin.BakeMesh(mesh,true);var pts=mesh.vertices;if(pts.Length!=footSet.vertexCount)throw new Exception("EOF original vertex count changed "+prefab.name+" expected="+footSet.vertexCount+" actual="+pts.Length);double bakeMs=clock.Elapsed.TotalMilliseconds;bool bodyMode=ReferenceEquals(g.shoePoints,o.defeatBodyPoints);float body=float.PositiveInfinity,floor=float.PositiveInfinity,error=0;foreach(var p in pts){var world=skin.transform.TransformPoint(p);if(float.IsNaN(world.y)||float.IsInfinity(world.y))summary.failed=true;body=Mathf.Min(body,world.y);}floor=bodyMode?body:feet.Min(i=>skin.transform.TransformPoint(pts[i]).y);float miss=g.UncorrectedMinimum-(floor-g.LastCorrection);
 if(segment=="settled"&&o.LastBlendWeight==1){e.pose.Apply(e.pose.Bind(ro.animator.transform),o.LastSamplePhase*e.pose.duration);ro.animator.transform.SetPositionAndRotation(o.animator.transform.position,o.animator.transform.rotation);ro.animator.transform.localScale=o.animator.transform.lossyScale;var hp=ro.animator.transform.InverseTransformPoint(refHip.position);hp.x=o.hipBindAnchor.x;hp.z=o.hipBindAnchor.z;refHip.position=ro.animator.transform.TransformPoint(hp);var rm=new Mesh();rs.BakeMesh(rm,true);var rp=rm.vertices;if(rp.Length!=pts.Length)summary.failed=true;else for(int i=0;i<pts.Length;i++)error=Mathf.Max(error,Vector3.Distance(skin.transform.TransformPoint(pts[i]),rs.transform.TransformPoint(rp[i])));Destroy(rm);summary.vertices+=pts.Length;if(error>2e-5f)summary.failed=true;}
 var hip=skin.bones.Single(t=>t.name.Substring(t.name.LastIndexOf(':')+1)=="Hips");var anchor=o.animator.transform.InverseTransformPoint(hip.position);float xz=new Vector2(anchor.x-o.hipBindAnchor.x,anchor.z-o.hipBindAnchor.z).magnitude;summary.samples++;summary.worstFloor=Mathf.Min(summary.worstFloor,floor);summary.maxSurfaceError=Mathf.Max(summary.maxSurfaceError,error);summary.maxRootXZ=Mathf.Max(summary.maxRootXZ,xz);if(floor<-.0005f||xz>1e-5f)summary.failed=true;
 rows.Add(string.Join(",",prefab.name,e.state,segment,frame,F(o.LastSamplePhase),F(o.LastBlendWeight),bodyMode,F(floor),F(body),F(miss),F(error),F(xz),F(bakeMs),F(renderMs),F(main.LastValue/1e6),F(render.LastValue/1e6),F(Time.unscaledDeltaTime*1000)));if(segment=="settled"||frame==0||frame==12||frame==23)Save(prefab.name+"-"+e.state+"-"+segment+"-"+frame);Destroy(mesh);
 }File.WriteAllLines(Path.Combine(output,"frames.csv"),rows);File.WriteAllText(Path.Combine(output,"summary.json"),JsonUtility.ToJson(summary,true));}}
 Destroy(actor);Destroy(refActor);yield return null;}
 summary.completed=true;File.WriteAllText(Path.Combine(output,"summary.json"),JsonUtility.ToJson(summary,true));main.Dispose();render.Dispose();Debug.Log("NATIVE_MAIN_PROBE "+JsonUtility.ToJson(summary));if(quitWhenComplete)Application.Quit(summary.failed?1:0);}
 void Save(string name){var rt=captureCamera.targetTexture;var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());RenderTexture.active=previous;Destroy(image);}
}
